def a_roman_to_integer(roman_numeral: str) -> int:
    """
    Converts a Roman numeral string into an integer.

    Args:
        roman_numeral (str): A string representing a Roman numeral.

    Returns:
        int: The integer equivalent of the Roman numeral.

    Raises:
        ValueError: If the input is not a valid Roman numeral.
    """
    # Ensure the input is a string
    assert isinstance(roman_numeral, str), "Input must be a string."

    # Define the mapping of Roman numerals to integers
    roman_map = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }

    # Initialize total and previous value
    total = 0
    prev_value = 0

    # Iterate over the Roman numeral string in reverse
    for char in reversed(roman_numeral):
        current_value = roman_map.get(char, 0)

        # If the current value is less than the previous value, subtract it
        # Otherwise, add it
        if current_value < prev_value:
            total -= current_value
        else:
            total += current_value

        prev_value = current_value

    # Check if the input is a valid Roman numeral
    assert all(char in roman_map for char in roman_numeral), "Invalid Roman numeral."

    return total
