from typing import List, Optional

class Playlist:
    def __init__(self):
        self.songs: List[str] = []

    @retry(max_attempts=3)
    def x_1_add_song(self, song: str) -> None:
        try:
            self.songs.append(song)
        except Exception as e:
            raise RuntimeError(f"Failed to add song: {e}")

    @retry(max_attempts=3)
    def x_2_remove_song(self, song: str) -> None:
        try:
            if song in self.songs:
                self.songs.remove(song)
            else:
                raise ValueError(f"Song '{song}' not found in playlist")
        except Exception as e:
            raise RuntimeError(f"Failed to remove song: {e}")
